async function listTodos(priority) {
  const todos = await readTodos();
  const createdTime = (todo) => {
    const ms = todo.createdAt ? Date.parse(todo.createdAt) : 0;
    return Number.isNaN(ms) ? 0 : ms;
  };
  const visible = todos
    .map((todo, i) => ({ todo, index: i + 1 }))
    .filter(({ todo }) => !priority || (todo.priority ?? 'normal') === priority)
    .sort((a, b) => createdTime(b.todo) - createdTime(a.todo));
  for (const { todo, index } of visible) {
    const suffix = todo.done ? ' [done]' : '';
    console.log(`${index}. ${todo.text}${suffix}`);
  }
}

